// find-email: find all email addresses in a string using regexped WASM.
// stub.ts is auto-generated by: regexped generate --config=regexped.yaml
import { find_email, find_email_user, find_email_domain, RX_ITER_ERROR } from "./stub";

function slice(buf: ArrayBuffer, start: i32, end: i32): string {
  return String.UTF8.decodeUnsafe(changetype<usize>(buf) + <usize>start, <usize>(end - start), false);
}

// The stub owns the iteration now: it advances past each match and applies
// Go's empty-match rule, which this loop used to hand-roll. Named groups are
// index constants — find_email_user, find_email_domain — and slot k of group g
// sits at slots + 8*g + 4*k.
function findEmails(text: string): void {
  console.log("input: " + text);
  const buf = String.UTF8.encode(text);
  const iter = find_email(buf, 0);
  let found = false;
  let slots = iter.next();
  while (slots != 0 && slots != RX_ITER_ERROR) {
    found = true;
    const matchStart = load<i32>(slots);
    const matchEnd   = load<i32>(slots + 4);
    const userStart  = load<i32>(slots + <usize>(8 * find_email_user));
    const userEnd    = load<i32>(slots + <usize>(8 * find_email_user + 4));
    const domStart   = load<i32>(slots + <usize>(8 * find_email_domain));
    const domEnd     = load<i32>(slots + <usize>(8 * find_email_domain + 4));
    console.log("  email:  " + slice(buf, matchStart, matchEnd));
    console.log("    user:   " + slice(buf, userStart, userEnd));
    console.log("    domain: " + slice(buf, domStart, domEnd));
    slots = iter.next();
  }
  if (slots == RX_ITER_ERROR) {
    // The engine gave up: what remains is UNKNOWN, not "no more emails".
    console.log("  (cannot decide: backtracking budget exhausted)");
    return;
  }
  if (!found) {
    console.log("  (no emails found)");
  }
}

findEmails("Contact alice@example.com or bob@company.org for details.");
findEmails("reach us at support@open-source.io and sales@widgets.co.uk");
findEmails("no emails here");
